import CoreServices
import Testing
@testable import CopipeCore

@Suite struct PasteboardMarkersTests {
    @Test(arguments: [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "jp.ichitai.copipestorage.clip",
    ])
    func skipsMarkedContent(marker: String) {
        #expect(PasteboardMarkers.shouldSkip(types: ["public.utf8-plain-text", marker]))
    }

    @Test func keepsOrdinaryContent() {
        #expect(!PasteboardMarkers.shouldSkip(types: ["public.utf8-plain-text", "public.rtf", "org.nspasteboard.source"]))
    }

    @Test(arguments: ["public.data", nil])
    func legacyMarkerAsDynamicUTIIsSkipped(conformsTo: String?) throws {
        let dynamic = try #require(
            UTTypeCreatePreferredIdentifierForTag(kUTTagClassNSPboardType, "Pasteboard generator type" as CFString, conformsTo as CFString?)?
                .takeRetainedValue() as String?
        )
        #expect(dynamic.hasPrefix("dyn."))
        #expect(PasteboardMarkers.shouldSkip(types: ["public.utf8-plain-text", dynamic]))
    }

    @Test func unrelatedDynamicUTIIsKept() throws {
        let dynamic = try #require(
            UTTypeCreatePreferredIdentifierForTag(kUTTagClassNSPboardType, "Some other legacy type" as CFString, nil)?
                .takeRetainedValue() as String?
        )
        #expect(!PasteboardMarkers.shouldSkip(types: ["public.utf8-plain-text", dynamic]))
    }

    @Test func sourceAndOwnMarkerAreMetadata() {
        #expect(PasteboardMarkers.isMetadataType("org.nspasteboard.source"))
        #expect(PasteboardMarkers.isMetadataType("jp.ichitai.copipestorage.clip"))
        #expect(!PasteboardMarkers.isMetadataType("public.rtf"))
    }
}
